import type { ImageLoaderProps } from "next/image";

// These files are generated by scripts/prepare-images.mjs before dev/build.
export default function imageLoader({ src, width }: ImageLoaderProps) {
  if (!src.startsWith("/images/") || !src.endsWith(".webp")) {
    throw new Error(`Unsupported responsive image: ${src}`);
  }
  const name = src.slice("/images/".length, -".webp".length);
  return `/images/optimized/${name}-${width}.webp`;
}
